public class Solution {
    static abstract sealed class Expression permits Constant, BinaryOp {
        public abstract int eval();
    }

    static final class Constant extends Expression {
        private final int val;
        public Constant(int v) { this.val = v; }
        @Override public int eval() { return val; }
    }

    static final class BinaryOp extends Expression {
        private final Expression left, right;
        public BinaryOp(Expression l, Expression r) { this.left = l; this.right = r; }
        @Override public int eval() { return left.eval() + right.eval(); }
    }

    public static void main(String[] args) {
        System.out.println("Implementation method executed");
        Expression expr = new BinaryOp(new Constant(20), new Constant(22));
        System.out.println("Result: " + (expr.eval() == 42 ? "Success" : "Failure"));
    }
}

