public class Solution {
    static abstract class AbstractFilter {
        private AbstractFilter next;

        public AbstractFilter linkWith(AbstractFilter next) {
            this.next = next;
            return next;
        }

        public void process(String data) {
            filter(data);
            if (next != null) next.process(data);
        }

        protected abstract void filter(String data);
    }

    static class AuthFilter extends AbstractFilter {
        @Override protected void filter(String data) { System.out.println("Parent method called"); }
    }

    static class LogFilter extends AbstractFilter {
        @Override protected void filter(String data) { System.out.println("Child method called"); }
    }

    public static void main(String[] args) {
        AbstractFilter chain = new AuthFilter();
        chain.linkWith(new LogFilter());
        chain.process("PAYLOAD");
    }
}

